import json
import re
from pathlib import Path
from playwright.sync_api import sync_playwright

SCOUT_JSON = Path(r"C:\Users\vamsh\.gemini\antigravity\brain\722d6332-73d9-49af-be4d-dd125c69723f\scratch\scouting.json")
OUT_JSON = Path(r"C:\Users\vamsh\.gemini\antigravity\brain\722d6332-73d9-49af-be4d-dd125c69723f\scratch\scout_content.json")

data = json.loads(SCOUT_JSON.read_text(encoding="utf-8"))
access_map = {s["siteId"]: s for s in data["access"]}

def clean_zw(s: str) -> str:
    if not s:
        return ""
    for ch in ["\u200b", "\u200c", "\u200d", "\ufeff", "\u00ad"]:
        s = s.replace(ch, "")
    return s

def unlock_gates(page):
    """Unlock any range+checkbox gates on the page."""
    page.evaluate("""() => {
        document.querySelectorAll('dialog[open] button[data-close]').forEach(b => b.click());
        document.querySelectorAll('input[type="range"]').forEach(slider => {
            slider.value = slider.max || 100;
            slider.dispatchEvent(new Event('input', {bubbles: true}));
            slider.dispatchEvent(new Event('change', {bubbles: true}));
        });
        document.querySelectorAll('section[aria-label="Zugangsprüfung"] input[type="checkbox"]').forEach(cb => {
            if (cb.name !== 'acknowledged' && !cb.checked) {
                cb.checked = true;
                cb.dispatchEvent(new Event('change', {bubbles: true}));
            }
        });
    }""")
    page.wait_for_timeout(150)

def login_and_consent(page, site):
    url = site["url"]
    creds = site["credentials"]
    page.goto(url, wait_until="domcontentloaded")
    page.wait_for_timeout(300)
    if page.locator('input[name="username"]').count() > 0:
        page.locator('input[name="username"]').fill(creds["username"])
        page.locator('input[name="password"]').fill(creds["password"])
        page.locator('button:has-text("Anmelden")').click()
        page.wait_for_load_state("domcontentloaded")
        page.wait_for_timeout(300)
    if "/consent" in page.url or page.locator('button:has-text("Cookies akzeptieren")').count() > 0:
        page.locator('button:has-text("Cookies akzeptieren")').first.click()
        page.wait_for_load_state("domcontentloaded")
        page.wait_for_timeout(300)
    for _ in range(3):
        body_txt = clean_zw(page.locator("body").inner_text())
        if "Dienst vorübergehend" in body_txt:
            page.goto(url, wait_until="domcontentloaded")
            page.wait_for_timeout(300)
        elif "Empfangsnummer" in body_txt and page.locator('input[name="receipt"]').count() > 0:
            unlock_gates(page)
            label = page.locator("canvas#erp-receipt").get_attribute("aria-label") or ""
            m = re.search(r"([A-Z]+-\d+)", label)
            if m:
                page.locator('input[name="receipt"]').fill(m.group(1))
                page.locator('input[name="acknowledged"]').check()
                page.locator('button:has-text("Weiter")').click()
                page.wait_for_load_state("domcontentloaded")
                page.wait_for_timeout(300)
        else:
            break

res = {}
with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)

    # 1. TENDER PORTAL: documents 0, 1, 2, questions-frame, and submission
    p_tp = browser.new_context().new_page()
    login_and_consent(p_tp, access_map["tender-portal"])
    tp_base = access_map["tender-portal"]["url"]
    res["tender_portal"] = {}
    for doc_idx in [0, 1, 2]:
        p_tp.goto(f"{tp_base}/tenders/VG-2027-7093/documents/{doc_idx}", wait_until="domcontentloaded")
        p_tp.wait_for_timeout(200)
        res["tender_portal"][f"doc_{doc_idx}"] = clean_zw(p_tp.locator("body").inner_text())

    p_tp.goto(f"{tp_base}/tenders/VG-2027-7093/questions-frame", wait_until="domcontentloaded")
    p_tp.wait_for_timeout(300)
    res["tender_portal"]["questions_frame_p1"] = {
        "text": clean_zw(p_tp.locator("body").inner_text()),
        "html": clean_zw(p_tp.content())
    }
    # Check if there are multiple pages or load more in questions-frame
    p_tp.goto(f"{tp_base}/tenders/VG-2027-7093/submission", wait_until="domcontentloaded")
    p_tp.wait_for_timeout(300)
    res["tender_portal"]["submission_p1"] = {
        "url": p_tp.url,
        "text": clean_zw(p_tp.locator("body").inner_text()),
        "html": clean_zw(p_tp.content())
    }

    # 2. CUSTOMER PORTAL: /documents/specification
    p_cp = browser.new_context().new_page()
    login_and_consent(p_cp, access_map["customer-portal"])
    cp_base = access_map["customer-portal"]["url"]
    p_cp.goto(f"{cp_base}/documents/specification", wait_until="domcontentloaded")
    p_cp.wait_for_timeout(300)
    res["customer_portal_spec"] = {
        "url": p_cp.url,
        "text": clean_zw(p_cp.locator("body").inner_text()),
        "html": clean_zw(p_cp.content())
    }

    # 3. ERP: after unlocking /notice
    p_erp = browser.new_context().new_page()
    login_and_consent(p_erp, access_map["erp"])
    res["erp_home"] = {
        "url": p_erp.url,
        "text": clean_zw(p_erp.locator("body").inner_text()),
        "html": clean_zw(p_erp.content())
    }

    # 4. MAIL: check inbox and archive messages
    p_mail = browser.new_context().new_page()
    login_and_consent(p_mail, access_map["mail"])
    mail_base = access_map["mail"]["url"]
    unlock_gates(p_mail)
    # Wait, why did inbox only show 2 messages earlier? Let's check what happens if we search VG-2027-7093 in inbox and archive!
    res["mail_searches"] = {}
    for folder in ["inbox", "archive"]:
        for q in ["VG-2027-7093", "VG-2027-7093 Rabatt", "VG-2027-7093 Freigabe", "VG-2027-7093 Konditionsregeln", "VG-2027-7093 Preisindizes", "VG-2027-7093 Verpackungstarife", "VG-2027-7093 Terminfreigabe", "VG-2027-7093 Devisenfixing", "VG-2027-7093 Rüstpools", "VG-2027-7093 Projektbonus", "VG-2027-7093 Technikfreigabe"]:
            p_mail.goto(f"{mail_base}/?folder={folder}&q={q}", wait_until="domcontentloaded")
            p_mail.wait_for_timeout(200)
            links = p_mail.evaluate("""() => Array.from(document.querySelectorAll('#messages a')).map(a => ({href: a.getAttribute('href'), text: a.innerText.trim()}))""")
            if links:
                res["mail_searches"][f"{folder}:{q}"] = links

    browser.close()

OUT_JSON.write_text(json.dumps(res, indent=2, ensure_ascii=False), encoding="utf-8")
print("Wrote", OUT_JSON)

