async def handle_gates_and_notices(page, target_url: str) -> str:
    """Handle cookie consent, ERP /notice receipt gate, customer-portal document access gate, and 503 retries."""
    text = ""
    for _ in range(5):
        text = await get_clean_text(page)

        # 1. Cookie consent wall
        if "Cookies" in text:
            consent_btn = page.locator(
                'button[value="accept"], button:has-text("Cookies akzeptieren"), button:has-text("Auswahl bestätigen")'
            )
            if await consent_btn.count() > 0:
                await consent_btn.first.click()
                await page.wait_for_load_state("domcontentloaded")
                continue

        # 2. Transient error page ("Dienst vorübergehend nicht verfügbar")
        if "Dienst vorübergehend nicht verfügbar" in text or "Anfrage konnte nicht verarbeitet werden" in text:
            await asyncio.sleep(0.2)
            await page.goto(target_url, wait_until="domcontentloaded")
            continue

        # 3. ERP Systemmitteilung receipt gate on /notice
        if "Empfangsnummer" in text or "/notice" in page.url:
            erp_receipt = page.locator("canvas#erp-receipt")
            if await erp_receipt.count() > 0:
                label = strip_zwc(await erp_receipt.first.get_attribute("aria-label") or "")
                code = label.split(":", 1)[-1].strip() if ":" in label else label.strip()
                receipt_input = page.locator('input[name="receipt"]')
                if await receipt_input.count() > 0:
                    await receipt_input.first.fill(code)
                ack_cb = page.locator('input[name="acknowledged"]')
                if await ack_cb.count() > 0:
                    await ack_cb.first.check()
                submit_btn = page.locator('form[action="/notice"] button[type="submit"], button:has-text("Weiter")')
                if await submit_btn.count() > 0:
                    await submit_btn.first.click()
                    await page.wait_for_load_state("domcontentloaded")
                    if page.url.rstrip("/") != target_url.rstrip("/"):
                        await page.goto(target_url, wait_until="domcontentloaded")
                    continue

        # 4. Customer portal Dokumentenüberlassung gate
        if "Dokumentenüberlassung" in text or "Empfangszeichen" in text:
            access_receipt = page.locator("canvas#access-receipt")
            if await access_receipt.count() > 0:
                label = strip_zwc(await access_receipt.first.get_attribute("aria-label") or "")
                code = label.split(":", 1)[-1].strip() if ":" in label else label.strip()
                ref_radio = page.locator('input[name="purpose"][value="reference"]')
                if await ref_radio.count() > 0:
                    await ref_radio.first.check()
                receipt_input = page.locator('input[name="receipt"]')
                if await receipt_input.count() > 0:
                    await receipt_input.first.fill(code)
                ack_cb = page.locator('input[name="acknowledged"]')
                if await ack_cb.count() > 0:
                    await ack_cb.first.check()
                read_btn = page.locator('button[name="operation"][value="read"]')
                if await read_btn.count() > 0:
                    await read_btn.first.click()
                    await page.wait_for_load_state("domcontentloaded")
                    continue

        break
    return text


async def safe_goto(page, url: str) -> str:
    """Navigate to `url`, resolve any gates or transient error pages, and return clean page text."""
    for attempt in range(4):
        try:
            await page.goto(url, wait_until="domcontentloaded", timeout=20000)
            text = await handle_gates_and_notices(page, url)
            if "Dienst vorübergehend nicht verfügbar" in text and attempt < 3:
                await asyncio.sleep(0.25 * (attempt + 1))
                continue
            return text
        except Exception:
            if attempt == 3:
                raise
            await asyncio.sleep(0.25 * (attempt + 1))
    return await get_clean_text(page)

    positions_by_id: dict[str, TenderPosition] = {}
    for d_url in doc_urls:
        d_text = await safe_goto(page, d_url)
        for pos in parse_tender_positions_from_text(d_text):
            if pos.position not in positions_by_id:
                positions_by_id[pos.position] = pos
        if positions_by_id:
            break

    # Discover Q&A URL (check iframe[src*="questions"] as well as links)
    qa_url = str(llm_docs.get("qa_url") or "")
    if not qa_url or "questions" not in qa_url:
        iframe_src = await page.evaluate(
            """() => {
            const ifr = document.querySelector('iframe[src*="questions"]');
            return ifr ? ifr.getAttribute('src') : null;
        }"""
        )
        if iframe_src:
            qa_url = urljoin(base_url, strip_zwc(iframe_src))
        else:
            qa_url = f"{base_url}/tenders/{tender_reference}/questions-content"

    qa_texts = await paginate_pages(page, qa_url, max_pages=15)
    clarifications = parse_qa_pages(qa_texts)

    # LLM reviews Q&A clarifications to verify withdrawn answers and quantity changes
    qa_summary = [
        {
            "number": c.number,
            "timestamp": c.timestamp.isoformat(),
            "withdrawn": c.withdrawn_number,
            "qty_changes": c.quantity_changes,
            "snippet": c.text[:160],
        }
        for c in clarifications
    ]
    await ask_llm_json(
        f"Review the extracted Q&A clarifications for tender '{tender_reference}' and confirm withdrawn question numbers "
        f"and final active quantity overrides:\n{json.dumps(qa_summary, ensure_ascii=False)}\n"
        f'Return JSON: {{"withdrawn_numbers": [...], "confirmed": true}}'
    )

    submission_url = str(llm_docs.get("submission_url") or "")
    if not submission_url or "/submission" not in submission_url:
        submission_url = f"{base_url}/tenders/{tender_reference}/submission"

    positions = sorted(positions_by_id.values(), key=lambda x: x.position)
    return positions, clarifications, submission_url


async def investigate_customer_portal(
    page,
    site_access: dict[str, Any],
    tender_reference: str,
    scenario_date: datetime,
    spec_ready_event: asyncio.Event,
    shared_state: dict[str, Any],
) -> tuple[str, dict[str, RequirementSpec]]:
    """Browser 1: LLM-directed investigation of the buyer's supplier portal (`customer-portal`)."""
    try:
        base_url = site_access["url"].rstrip("/")
        landing_text = await login_portal(page, site_access)
        landing_links = await get_actionable_links(page, base_url)

        llm_nav = await ask_llm_json(
            f"We need the technical specification (Lastenheft) for tender '{tender_reference}' on the supplier portal.\n"
            f"Observed text:\n{landing_text[:1200]}\n"
            f"Observed links:\n{json.dumps(landing_links[:20], ensure_ascii=False)}\n"
            f'Return JSON: {{"spec_url": "<selected full url>"}}'
        )
        spec_url = str(llm_nav.get("spec_url") or "")
        if not spec_url or "/documents" not in spec_url:
            for lnk in landing_links:
                if "/documents/specification" in lnk["url"]:
                    spec_url = lnk["url"]
                    break
            if not spec_url:
